   var parent=soundPopup.activeSelf?soundPopup.transform:Canvas.transform;var selectables=parent.GetComponentsInChildren<Selectable>().Where(s=>s.gameObject.activeInHierarchy&&s.IsInteractable()).ToArray();if(selectables.Length==0)return false;int current=Array.FindIndex(selectables,s=>s.gameObject==EventSystem.current.currentSelectedGameObject);int step=Input.GetKey(KeyCode.LeftShift)?-1:1;EventSystem.current.SetSelectedGameObject(selectables[(current+step+selectables.Length)%selectables.Length].gameObject);
  }
  return false;
 }
